/**
 * The 5 by 5 glyphs for the `characters` style: 0-9, A-F, then + - > / * = _.
 * `#` is a lit pixel. Rows run top to bottom.
 */
const GLYPHS = [
  [".###.", "#..##", "#.#.#", "##..#", ".###."],
  ["..#..", ".##..", "..#..", "..#..", ".###."],
  ["####.", "....#", ".###.", "#....", "#####"],
  ["####.", "....#", ".###.", "....#", "####."],
  ["#..#.", "#..#.", "#####", "...#.", "...#."],
  ["#####", "#....", "####.", "....#", "####."],
  [".###.", "#....", "####.", "#...#", ".###."],
  ["#####", "....#", "...#.", "..#..", "..#.."],
  [".###.", "#...#", ".###.", "#...#", ".###."],
  [".###.", "#...#", ".####", "....#", ".###."],
  [".###.", "#...#", "#####", "#...#", "#...#"],
  ["####.", "#...#", "####.", "#...#", "####."],
  [".####", "#....", "#....", "#....", ".####"],
  ["####.", "#...#", "#...#", "#...#", "####."],
  ["#####", "#....", "####.", "#....", "#####"],
  ["#####", "#....", "####.", "#....", "#...."],
  [".....", "..#..", ".###.", "..#..", "....."],
  [".....", ".....", ".###.", ".....", "....."],
  [".#...", "..#..", "...#.", "..#..", ".#..."],
  ["....#", "...#.", "..#..", ".#...", "#...."],
  [".....", "#.#.#", ".###.", "#.#.#", "....."],
  [".....", "#####", ".....", "#####", "....."],
  [".....", ".....", ".....", ".....", "#####"],
] as const;

const GLYPH_SIZE = 5;

/** One bitmask per glyph, as `uFont` in screen.frag reads it: bit row * 5 + column. */
export const FONT_BITS = Uint32Array.from(GLYPHS, (rows) => {
  let bits = 0;
  rows.forEach((row, rowIndex) => {
    for (let column = 0; column < GLYPH_SIZE; column++) {
      if (row[column] === "#") bits += 2 ** (rowIndex * GLYPH_SIZE + column);
    }
  });
  return bits;
});
